{"source":"npm:@earendil-works/pi-coding-agent@1.4.0/examples/extensions/custom-compaction.ts","start":0,"end":3971,"sha256":"ea797b3508fd8600526f381466e8b08bb84f3d234932a9d6ce512698527d0aa9","fixed_item_ids":["pi-optional-sdk-examples.0026","pi-optional-sdk-examples.0027","pi-optional-sdk-examples.0028","pi-optional-sdk-examples.0029","pi-optional-sdk-examples.0030","pi-optional-sdk-examples.0031","pi-optional-sdk-examples.0032"],"catch_routes":[{"path":"examples/extensions/custom-compaction.ts","physical_source":"examples/extensions/custom-compaction.ts","start":3751,"end":3963,"line":110,"column":5,"physical_line":110,"raw_source":"catch (error) {
			const message = error instanceof Error ? error.message : String(error);
			ctx.ui.notify(`Compaction failed: ${message}`, "error");
			// Fall back to default compaction on error
			return;
		}","disposition":"Replace caught failure with Compaction failed notice containing Error.message/String then return undefined for native fallback; notify even local abort."}],"promise_catches":[]}

{"source":"npm:@earendil-works/pi-coding-agent@1.4.0/examples/extensions/custom-provider-anthropic/index.ts","start":0,"end":19811,"sha256":"52bb733e1a25d9e175a644e6a6e17bbf61071beecf0f2903869baa9579a05ab3","fixed_item_ids":["pi-optional-sdk-examples.0033","pi-optional-sdk-examples.0034","pi-optional-sdk-examples.0035","pi-optional-sdk-examples.0036","pi-optional-sdk-examples.0037","pi-optional-sdk-examples.0038","pi-optional-sdk-examples.0039","pi-optional-sdk-examples.0040","pi-optional-sdk-examples.0041","pi-optional-sdk-examples.0042","pi-optional-sdk-examples.0043"],"catch_routes":[{"path":"examples/extensions/custom-provider-anthropic/index.ts","physical_source":"examples/extensions/custom-provider-anthropic/index.ts","start":16068,"end":16076,"line":512,"column":9,"physical_line":512,"raw_source":"catch {}","disposition":"Ignore partial tool JSON parse failure, continue streaming prior arguments/partial delta."},{"path":"examples/extensions/custom-provider-anthropic/index.ts","physical_source":"examples/extensions/custom-provider-anthropic/index.ts","start":17058,"end":17066,"line":535,"column":9,"physical_line":535,"raw_source":"catch {}","disposition":"Ignore final tool JSON parse failure, emit toolcall_end with existing arguments."},{"path":"examples/extensions/custom-provider-anthropic/index.ts","physical_source":"examples/extensions/custom-provider-anthropic/index.ts","start":18329,"end":18670,"line":565,"column":5,"physical_line":565,"raw_source":"catch (error) {
			for (const block of output.content) delete (block as any).index;
			output.stopReason = options?.signal?.aborted ? "aborted" : "error";
			output.errorMessage = error instanceof Error ? error.message : JSON.stringify(error);
			stream.push({ type: "error", reason: output.stopReason, error: output });
			stream.end();
		}","disposition":"Strip temporary block indices; local signal chooses aborted/error, normalize Error.message or JSON.stringify(error), push error event/end. JSON.stringify/listener throws may preempt terminal."}],"promise_catches":[]}

{"source":"npm:@earendil-works/pi-coding-agent@1.4.0/examples/extensions/custom-provider-gitlab-duo/index.ts","start":0,"end":12148,"sha256":"0c4adac82eff25fef23223af77e11cd53535834fece9731009b125446e213158","fixed_item_ids":["pi-optional-sdk-examples.0044","pi-optional-sdk-examples.0045","pi-optional-sdk-examples.0046","pi-optional-sdk-examples.0047","pi-optional-sdk-examples.0048","pi-optional-sdk-examples.0049","pi-optional-sdk-examples.0050","pi-optional-sdk-examples.0051","pi-optional-sdk-examples.0052","pi-optional-sdk-examples.0053","pi-optional-sdk-examples.0054","pi-optional-sdk-examples.0055","pi-optional-sdk-examples.0056","pi-optional-sdk-examples.0057","pi-optional-sdk-examples.0058","pi-optional-sdk-examples.0059","pi-optional-sdk-examples.0060","pi-optional-sdk-examples.0061"],"catch_routes":[{"path":"examples/extensions/custom-provider-gitlab-duo/index.ts","physical_source":"examples/extensions/custom-provider-gitlab-duo/index.ts","start":10817,"end":11376,"line":348,"column":5,"physical_line":348,"raw_source":"catch (error) {
			stream.push({
				type: "error",
				reason: "error",
				error: {
					role: "assistant",
					content: [],
					api: model.api,
					provider: model.provider,
					model: model.id,
					usage: {
						input: 0,
						output: 0,
						cacheRead: 0,
						cacheWrite: 0,
						totalTokens: 0,
						cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
					},
					stopReason: "error",
					errorMessage: error instanceof Error ? error.message : String(error),
					timestamp: Date.now(),
				},
			});
			stream.end();
		}","disposition":"Convert caught token/fetch/provider error to zero-usage assistant error event using Error.message/String; always reason=error, end stream. Native event listener failures can preempt."}],"promise_catches":[]}

{"source":"npm:@earendil-works/pi-coding-agent@1.4.0/examples/extensions/github-issue-autocomplete.ts","start":0,"end":5282,"sha256":"4646ef360e57aa98c787ba21ca2f2e8acb3db30c4db0503e64cdbea4a4c2ac65","fixed_item_ids":["pi-optional-sdk-examples.0116","pi-optional-sdk-examples.0117","pi-optional-sdk-examples.0118","pi-optional-sdk-examples.0119","pi-optional-sdk-examples.0120","pi-optional-sdk-examples.0121","pi-optional-sdk-examples.0122","pi-optional-sdk-examples.0123"],"catch_routes":[{"path":"examples/extensions/github-issue-autocomplete.ts","physical_source":"examples/extensions/github-issue-autocomplete.ts","start":4917,"end":5114,"line":171,"column":7,"physical_line":171,"raw_source":"catch {
